publish > kafka publishing: kafka publishMessage | topic.bootstrapServers="kafka.example.com" topic.topicName="documents" | authentication.type=credentials authentication.username=admin authentication.password={{secrets.KAFKA_PASSWORD}}
routing_check > kafka routing_check: kafka publishMessage | topic.bootstrapServers="kafka.example.com" topic.topicName="routing topics" | authentication.type=credentials authentication.username=admin authentication.password={{secrets.KAFKA_PASSWORD}} message.key==contractId
inform > textract extract: textract extractDocument | configuration.region="us-west-2" input.documentS3Bucket=="${documentCamundaReference}PdfBucket" input.documentName=="${documentCamundaReference}PdfName" | authentication.type=credentials authentication.accessKey={{secrets.AWS_ACCESS_KEY}} authentication.secretKey={{secrets.AWS_SECRET_KEY}} | resultVariable=extractedText: responseBody.Blocks[?(@.BlockType == 'LINE')].Text.toString().join('\n')

connect.lines:
with notify: send-message-end send | tenantId=tenantId | messageName=messageName
with error: lambda invoke | secret={{secrets.AWS_ACCESS_KEY}} | secretKey={{secrets.AWS_SECRET_KEY}} | region=us-east-1 | awsFunction=resize_image_lambda | body={ "originalImage": "${messageBody}" }
with dispatch: sqs send | secret={{secrets.AWS_ACCESS_KEY}} | secretKey={{secrets.AWS_SECRET_KEY}} | awsFunction=sqs_url | messageBody='orderId: ' + orderId

connect.raw:
notify: send-message-end send | tenantId=tenantId | messageName=messageName
error: lambda invoke | secret={{secrets.AWS_ACCESS_KEY}} | secretKey={{secrets.AWS_SECRET_KEY}} | region=us-east-1 | awsFunction=resize_image_lambda | body={ "originalImage": "${messageBody}" }
dispatch: sqs send | secret={{secrets.AWS_ACCESS_KEY}} | secretKey={{secrets.AWS_SECRET_KEY}} | awsFunction=sqs_url | messageBody='orderId: ' + orderId

write_page: http POST /v1/pages | api=notion | method=POST | body=={
  "object": "block",
  "type": "child_page",
  "title": [{ "type": "text", "text": { "content": "Ticket " + orderId } }]
} | headers=={ "Notion-Version": "2026-03-11" } | result=pageId: response.body.id
notify: slack chat.postMessage | token={{secrets.SLACK_TOKEN}} | data.channel=ops | data.text=="Ticket " + orderId + " created page successfully"
